AuctioneerLocalizations.deDE = {

		-- Section: Help
		["AAMU_Help_VendorOptions"]	= "AAMU: Verkaufsoptionen";
		["AAMU_Help_VendorOptionsAnswer"]	= "Mit AutoMagic werden Gegenstände, die nur zum Verkauf an den Händler gekauft wurden, automatisch verkauft. Es ist auch möglich, alle grauen Gegenstände und die Gegenstände aus der Verkaufsliste automatisch zu verkaufen.";
		["AAMU_Help_WhatAutoMagic"]	= "Was ist AutoMagic?";
		["AAMU_Help_WhatAutoMagicAnswer"]	= "AutoMagic ist zur Zeit noch im Aufbau. Das Ziel ist es, unbequeme Arbeitsabläufe zu automatisieren, soweit dies innerhalb der durch Blizzard gesetzten Grenzen möglich ist. \n\nIm Moment verkauft AutoMagic automatisch Gegenstände, die mittels SearchUI zum Verkauf an Händler gekauft wurden, jegliche grauen Gegenstände (wenn eingeschaltet), oder jegliche Gegenstände in der Auto-Verkaufsliste. Wenn aktiviert, zeigt AutoMagic auch eine Liste der zu verkaufenden Gegenstände, sobald ein Händlerfenster geöffnet wird.";
		["AAMU_Help_WhatMailGUI"]	= "Was ist die Post-GUI?";
		["AAMU_Help_WhatMailGUIAnswer"]	= "Wenn der Briefkasten geöffnet wird, wird ein zusätzliches Fenster angezeigt, mit dem automatisch Gegenstände in das 'Post versenden'-Fenster übernommen werden können, basierend auf den SearchUI-Regeln. Alternativ können auch die ItemSuggest-Regeln verwendet werden. Sehr praktisch zum 'Mass-Mailing' von Gegenständen, die für den Beruf eines anderen Charakters gekauft wurden.";
		["ADV_Help_CannotDeleteProfile"]	= "Das gewählte Profil kann nicht gelöscht werden.";
		["ADV_Help_InvalidProfileName"]	= "Konnte Profil nicht erstellen: Bitte gib zuerst einen neuen Profilnamen ein";
		["ADV_Help_PostAuctionError"]	= "Dieser Gegenstand kann nicht eingestellt werden, wegen folgendem Fehler: %s";
		["ADV_Help_UnresolvedAuctionsTolerance"]	= "Auctioneer ist manchmal nicht in der Lage, eine bestimmte Anzahl von Auktionen bei einem Scan zu lösen, so dass der Scan unvollständig ist. Der Toleranz der ungelöste Auktionen  ermöglicht Auctioneer noch die gescannte Items als erledigt zu markieren, wenn die Anzahl dieser Fehler sehr klein ist. Kann nützlich sein, wenn der Server instabil ist, insbesondere nach größeren Patches.";
		["ADV_Help_WhatAccuracy"]	= "Was ist der Marktpreis-Fehler?";
		["ADV_Help_WhatAccuracyAnswer"]	= "Der Marktpreis-Fehler erlaubt es, die Fehlertoleranz für die Berechnung des Marktpreises einzustellen. Da der Algorithmus extrem komplex ist, kann der Marktpreis eigentlich nur geschätzt werden. Eine kleinere Fehlertoleranz erhöht die Genauigkeit der Schätzung, benötigt aber mehr Rechenzeit (und kann damit auf älteren Rechnern zu langsam sein).";
		["ADV_Help_WhatClickHooks"]	= "Was sind Click-Hooks?";
		["ADV_Help_WhatClickHooksAnswer"]	= "Click-Hooks erlauben es, mit ALT-Rechtsklick nach Gegenständen aus den Taschen oder solchen, die im Chatfenster verlinkt wurden, zu suchen.";
		["ADV_Help_WhatExactMatch"]	= "Was ist ein genauer Treffer?";
		["ADV_Help_WhatExactMatchAnswer"]	= "Einige Gegenstände unterscheiden sich durch ihren Zusatz (z.B. des Bären/Adlers/Wiesels usw.), oder durch ihre genauen Werte (z.B. zwei Gegenstände des Bären mit unterschiedlichen Werten). Ein genauer Treffer läßt nur Gegenstände zu, die den Vorgaben 100% entsprechen.";
		["ADV_Help_WhatIsImage"]	= "Was ist ein Auktionshaus-Auszug?";
		["ADV_Help_WhatIsImageAnswer"]	= "Wenn Ihr das Auktionshaus scannt, baut Auctioneer eine Momentaufnahme dessen auf, was sich zur Zeit im Auktionshaus befindet. Dies ist der Auszug. Er repräsentiert die bestmögliche Annäherung an das, was gerade zum Verkauf steht. Wenn der Scan vor kurzem erst ausgeführt wurde, wird der Auszug ziemlich zuverlässig sein; sollte der Scan schon älter sein, eher nicht.";
		["ADV_Help_WhatIsScanData"]	= "Was ist der Daten-Tooltip?";
		["ADV_Help_WhatIsScanDataAnswer"]	= "Der Daten-Tooltip ist die Zeile in eurem Tooltip, die euch darüber informiert, wie viele Exemplare des aktuellen Gegenstandes zur Zeit im Auktionshausauszug zu finden sind.";
		["ADV_Help_WhatPreferredChatFrame"]	= "Was ist das bevorzugte Ausgabefenster?";
		["ADV_Help_WhatPreferredChatFrameAnswer"]	= "Mit dem bevorzugten Ausgabefenster könnt Ihr angeben, in welches Chatfenster Auctioneer seine Ausgaben schreiben wird. Wählt eins der Fenster aus dem Drop-Down-Menü und Auctioneer wird alle weiteren Ausgaben in dieses Fenster schreiben.";
		["ADV_Help_WhatPreferredLanguage"]	= "Was ist die bevorzugte Sprache?";
		["ADV_Help_WhatPreferredLanguageAnswer"]	= "Die bevorzugte Sprache erlaubt Euch zu entscheiden welche der unterstützten Sprachen Auctioneer benutzen soll. Dies kann sinnvoll sein wenn Auctioneer eine andere Spache als die des Spielclients benutzen soll.\nDies benötigt einen Neustart oder /reloadui.";
		["ADV_Help_WhatPriority"]	= "Was ist die Verarbeitungspriorität?";
		["ADV_Help_WhatPriorityAnswer"]	= "Die Verarbeitungspriorität beeinflusst die Geschwindigkeit der Datenverarbeitung nach dem Ende des Scannens. Niedrigere Werte brauchen länger, beeinflussen die Spielgeschwindigkeit aber weniger. Höhere Werte benötigen weniger Zeit, können aber zu Stockungen im Spiel führen. Die neuen Daten sind erst nach dem Ende der Verarbeitung verfügbar.";
		["ADV_Help_WhyForceLoad"]	= "Wann sollte man das Laden der Daten erzwingen?";
		["ADV_Help_WhyForceLoadAnswer"]	= "Wenn die Auktionshausdaten im Spiel genutzt werden sollen, ist es manchmal angenehmer, beim Start des Spiels etwas länger zu warten, anstatt Ruckler oder Spielunterbrechungen hinnehmen zu müssen, falls die Daten erst dann geladen werden, wenn sie benötigt werden.";
		["ADV_Help_WhyShowSummation"]	= "Was ist die Scan-Zusammenfassung?";
		["ADV_Help_WhyShowSummationAnswer"]	= "Die Zusammenfassung zeigt die Anzahl der neuen, geänderten oder gleichgebliebenen Auktionen nach dem Ende eines Auktionshaus-Scans an.";
		["AHWC_Help_AuctionHouseScale"]	= "Auktionshausfenstergröße?";
		["AHWC_Help_AuctionHouseScaleAnswer"]	= "Der Auktionsschieberegler verändert die Größe des gesamten Auktionshausfensters. Standard ist 1.";
		["AHWC_Help_CompactUIFontScale"]	= "CompactUI Schriftgröße?";
		["AHWC_Help_CompactUIFontScaleAnswer"]	= "Der CompactUI-Schriftgrößenregler verändert die Textgröße, mit der das CompactUI-Fenster angezeigt wird. Standard ist 0.";
		["AHWC_Help_ProtectWindow"]	= "Was bewirkt der Schutz des AH-Fensters?";
		["AHWC_Help_ProtectWindowAnswer"]	= "Das Auktionsfenster schließt sich normalerweise, wenn Ihr andere Fenster öffnet, wie z.B. das Geselligkeitsfenster, das Questlog oder die Berufefenster. Diese Option erlaubt es, das Fenster hinter den anderen geöffnet zu halten.";
		["AHWC_Help_RemberLastPosition"]	= "Letzte bekannte Fensterposition merken?";
		["AHWC_Help_RemberLastPositionAnswer"]	= "Ist diese Option aktiviert, wird sich das Auktionsfenster an der Stelle wieder öffnen, an die es zuletzt bewegt wurde.";
		["AHWC_Help_SearchUIScale"]	= "SearchUI Größe?";
		["AHWC_Help_SearchUIScaleAnswer"]	= "Der SearchUI-Schieberegler verändert die allgemeine Größe des Nicht-Auktions-SearchUI-Fensters. Standard ist 1.";
		["AHWC_Help_whatisthis"]	= "Was für ein Hilfsmittel ist das?";
		["AHWC_Help_whatisthisAnswer"]	= "Dieses Hilfsmittel erlaubt Euch das Auktionsfenster zu ziehen und für diese Sitzung an eine andere Stelle zu bewegen. Nutzt diese Option und bewegt das Fenster wohin Ihr möchtet. Ebenfalls wird dann das Auktionsfenster nicht mehr geschlossen, wenn Ihr bestimmte Blizzard Fenster öffnet.";
		["APPR_Help_BatchFollowingWouldPosted"]	= "Die folgenden Gegenstände werden automatisch eingestellt:";
		["APPR_Help_BatchPostHelp1"]	= "Der Posteneinstellungsmechanismus wird es Euch ermöglichen, automatisierte Aktionen für sämtliche Gegenstände in Eurem Inventar durchzuführen, die für Posteneinstellung markiert sind.";
		["APPR_Help_BatchPostHelp2"]	= "Ihr müsst eine der folgenden Tasten gedrückt halten, wenn Ihr auf den Button klickt:";
		["APPR_Help_BatchPostHelp3"]	= "- ALT = Automatische Auffrischung sämtlicher Gegenstände, die als Posten einstellbar sind.";
		["APPR_Help_BatchPostHelp4"]	= "- UMSCHALTTASTE = Listet sämtliche Auktionen auf, die eingestellt werden sollen ohne sie tatsächlich einzustellen.";
		["APPR_Help_BatchPostHelp5"]	= "- Rechtsklick = Automatische Einstellung sämtlicher Gegenstände, die als Posten einstellbar sind.";
		["APPR_Help_BatchPostHelp6"]	= "Alt+Rechts-Klicke einen Gegenstand um Posteneinstellung aus/an zu schalten.";
		["APPR_Help_BatchUnknownKeyCombo"]	= "Es wurde während des Klickens des Posteneinstellungsbuttons eine unbekannte Tastenkombination gedrückt.";
		["APPR_Help_CannotPostAuctions"]	= "Die Auktion kann nicht eingestellt werden:";
		["APPR_Help_CouldNotPost"]	= "Der Gegenstand kann nicht eingestellt werden.";
		["APPR_Help_CouldNotQueue"]	= "Der Gegenstand kann nicht in die Warteschlange aufgenommen werden.";
		["APPR_Help_Duration"]	= "Dauer: {{%d hours}}";
		["APPR_Help_HowBidPriceCalculated"]	= "Wie wird das Gebot berechnet?";
		["APPR_Help_HowBidPriceCalculatedAnswer"]	= "Das Startgebot wird, außer für Festpreis-Auktionen, auf Basis des ursprünglichen Sofortkaufspreises errechnet. Mit den Optionen zur Festsetzung des Gebotspreises kann man festlegen, um wieviel der Gebotspreis reduziert wird. Diese Optionen sind kumulativ. Das bedeutet, daß wenn der prozentuale Preisabschlag heruntergesetzt wird und die Einstellgebühr abgezogen wird, der Angebotspreis wie folgt kalkuliert wird: (%s Buyout %s-%s Markdown %s-%s Deposit %s)";
		["APPR_Help_HowMarkdownPctCalculated"]	= "Wie wird der Prozentsatz des Preisabschlages kalkuliert?";
		["APPR_Help_HowMarkdownPctCalculatedAnswer"]	= "Die Summe wird durch die Multiplikation des kalkulierten Wertes mit dem Prozentbetrag berechnet, der in den Optionen näher spezifiziert ist. Dieser Betrag wird dann zur Erzeugung des Startgebotspreises von dem kalkulierten Wert abgezogen (gemeinsam mit dem festen Abzugsbetrag und/oder der Hinterlegungssumme, falls näher spezifiziert).";
		["APPR_Help_NeedOnlyHavePosting"]	= "Benötige %d von %s : Verfüge nur über %d , Stelle %d ein.";
		["APPR_Help_PostedItems"]	= "{{%d}} Gegenstände eingestellt";
		["APPR_Help_PostingBatch"]	= "Stelle Posten von %s ein.";
		["APPR_Help_PostingItems"]	= "Stelle {{%d}} Gegenstände ein";
		["APPR_Help_PostingLots"]	= "Stelle {{%d}} Stapel {{%d}} ein";
		["APPR_Help_PretendedItems"]	= "Markiere {{%d}} Gegenstände.";
		["APPR_Help_PretendingPostStacks"]	= "Simuliere die Einstellung von {{%d}} Stapeln {{%d}} mit {{%s}} Mindestgebot und {{%s}} Sofortkauf pro Stapel.";
		["APPR_Help_QueuedUpItems"]	= "Habe {{%d}} Gegenstände in der Warteschleife.";
		["APPR_Help_QueueingItems"]	= "Reihe {{%d}} Gegenstände ein.";
		["APPR_Help_QueueingLots"]	= "Reihe {{%d}} Posten von {{%d}} ein.";
		["APPR_Help_SkippingInvalidBuyoutValue"]	= "Lasse %s aus: ungültiger Aufkaufwert";
		["APPR_Help_SkippingInvalidDuration"]	= "Lasse %s aus - ungültige Dauer:";
		["APPR_Help_SkippingInvalidNumberStacks"]	= "Lasse %s aus: Einstellung einer ungültigen Anzahl von Stapeln/Gegenständen.";
		["APPR_Help_SkippingNoAuctionableItem"]	= "Lasse %s aus: keine einstellbaren Gegenstände in den Taschen. Gegenstand muss möglicherweise repariert werden.";
		["APPR_Help_SkippingNoBidValue"]	= "Lasse %s aus: es wurde kein Gebotswert eingestellt.";
		["APPR_Help_SkippingNoStackSize"]	= "Lasse %s aus: es wurde keine Stapelgröße eingestellt.";
		["APPR_Help_SkippingNotEnoughItems"]	= "Lasse %s aus: Sie haben nicht genügend Gegenstände, um diese Aktion durchzuführen.";
		["APPR_Help_SkippingStackLargerAvailable"]	= "Lasse %s aus: Stapelgröße ist größer als verfügbar.";
		["APPR_Help_StacksAreadyPosted"]	= "%d Stapel von %s wurden bereits eingestellt.";
		["APPR_Help_TotalBuyoutValue"]	= "Gesamtpreis für den Sofortkauf: %s";
		["APPR_Help_TotalMinbidValue"]	= "Gesamtwert für das Minimalgebot: %s";
		["APPR_Help_WhatAppraiser"]	= "Was ist Appraiser (zu Deutsch: Schätzer)?";
		["APPR_Help_WhatAppraiserAnswer"]	= "Appraiser ist ein Werkzeug, das es Euch ermöglicht, schnell Auktionen einzustellen und daß sich automatisch Eure zuletzt eingestellten Preise merkt. Das Appraiser-Interface fügt sich unten an das Auktionshausfenster als zusätzliche Registerkarte an. Wenn Ihr zum ersten Mal das Appraiserfenster auswählt, werden sämtliche einstellbaren Gegenstände zur linken Seite des Fensters angezeigt werden. Wählt Ihr einen Gegenstand zur Linken aus, werdet Ihr oben das Kontrollfenster und unten sämtliche zur Zeit erhältlichen Auktionen aufgelistet sehen. Das Kontrollfenster ermöglicht es Euch die einzustellende Postengröße, die Einstellung für das Aufteilen von Stapeln, sowie die Anzahl der einzustellenden Posten durch das Verschieben zweier Schieberegler näher zu spezifizieren.";
		["APPR_Help_WhatClickHooks"]	= "Was sind Klick-Haken?";
		["APPR_Help_WhatClickHooksAnswer"]	= "Click-Hooks ermöglichen es Euch, einen Gegenstand per ALT-Klick auszuwählen, oder ihn per ALT-UMSCHALTTASTE-Klick einzustellen.";
		["APPR_Help_WhatDefaultPricing"]	= "Wofür wird das Standard-Preismodell verwendet?";
		["APPR_Help_WhatDefaultPricingAnswer"]	= "Wenn Appraiser den Preis kalkuliert, zu dem ein Gegenstand eingestellt werden soll, wird als Grundlage entweder der Marktpreis, der sich aus dem Durchschnitt bestimmter anderer Preismodelle bildet, oder ein Preis, der von einem spezifischen AutioneerAdvanced Statistikmodul ausgegeben wird, verwendet. Für Gegenstände, für die noch kein spezifisches Modell ausgewählt wurde, könnt Ihr selbst das zu verwendende Modell auswählen.";
		["APPR_Help_WhatStartingBid"]	= "Was ist das Startgebot?";
		["APPR_Help_WhatStartingBidAnswer"]	= "Das Startgebot ist auch als Mindestgebot bekannt. Es handelt sich hier um den Preis, dem der erste Bieter gleichkommen oder den er überbieten muss, um sein Gebot setzen zu können. Von diesem Wert ausgehend müssen die folgenden Gebote in Schritten ansteigen, die auf dem aktuellen Gebot basieren.";
		["ASAL_Help_StatSales"]	= "Was sind Verkaufsstatistiken?";
		["ASAL_Help_StatSalesAnswer"]	= "Verkaufsstatistiken sind Angaben aus dem Modul BeanCounter. Sie geben den Durchschnittpreis Ihrer verkauften Gegenstände an.";
		["ASKP_Help_WhatAskPrice"]	= "Was ist AskPrice und was macht es?";
		["ASKP_Help_WhatAskPriceAnswer"]	= "AskPrice ist ein Modul, daß es anderen Spielern erlaubt, den Wert bestimmter Gegenstände zu erfragen, in dem sie bestimmte Nachrichten in verschiedenen Chat-Kanälen posten, oder Euch direkt per /whisper ansprechen.";
		["ASKP_Help_WhatTriggers"]	= "Was sind diese Auslöser, und wie benutzt man sie?";
		["ASKP_Help_WhatTriggersAnswer"]	= "Auslöser legen fest, wie Euch jemand nach einem Preis fragen kann. \nDie frei wählbaren SmartWords erlauben es Auctioneer, auf umgangssprachliche Anfragen zu reagieren, während das Auslöse-Zeichen die Abfrage vonStapelgrößen erlaubt. \n\nDie Voreinstellung der SmartWords reagiert auf \'Was ist [item link] wert=\' \nDie Voreinstellung des Auslöse-Zeichens reagiert auf \'? (Stapelgröße) [item link]\'";
		["BASC_Help_IgnoreOwnAuctionsAnswer"]	= "Durch Markierung dieser Box wird das Hinzufügen von selbst eingestellten Auktionen zur Momentaufnahme deaktiviert.";
		["BASC_Help_WhatBasicFilter"]	= "Was ist der Basisfilter?";
		["BASC_Help_WhatBasicFilterAnswer"]	= "Dieser Filter ermöglicht es Euch, bestimmte Mindestbedingungen wie die minimale Gegenstandsstufe oder die minimale Qualität (Plunder, Ordinär, Ungewöhnlich, Selten, etc.) für einen Gegenstand zur Erfassung näher zu spezifizieren. Er gibt Euch auch die Möglichkeit, Gegenstände von einem bestimmten Anbieter zu spezifizieren, die nicht aufgenommen werden sollen. Eine Verwendungsmöglichkeit ist z.B. das Ignorieren sämtlicher Gegentände eines bestimmten Verkäufers, der seine Gegenstände weit über oder unter dem Marktpreis verkauft.";
		["COMP_Help_HowToIgnore"]	= "Wie ignoriere ich die Auktionen eines Verkäufers?";
		["COMP_Help_HowToIgnoreAnswer"]	= "ALT-Klickt auf den Namen des Verkäufers den Ihr ignorieren wollt, und wählt ja im Popup-Fenster. Der Name des Verkäufers wird Rot markiert und in die Ignore-Liste der Basisfilter-Module eingetragen.";
		["COMP_Help_HowToUnignore"]	= "Wie entferne ich das Ignorieren von Auktionen eines Verkäufers?";
		["COMP_Help_HowToUnignoreAnswer"]	= "ALT+Klickt auf den Verkäufer den Ihr aus der Ignore-Liste entfernen wollt, und wählt ja im Popup-Fenster. Der Name des Verkäufers wird dann aus der Ignore-Liste der Basisfilter-Module wieder entfernt.";
		["COMP_Help_WhatBrowseOverride"]	= "Warum sollte ich andere Module daran hindern, das Browse-Fenster zu verändern?";
		["COMP_Help_WhatBrowseOverrideAnswer"]	= "Wenn Ihr Module wie z.B. ScanProgress installiert und aktiviert habt, werden diese das Browse-Fenster verändern, so daß Ihr die Gegenstände, die gerade eingelesen werden nicht sehen könnt. Diese Einstellung deaktiviert diese Module während des Einlesevorgangs.";
		["COMP_Help_WhatCollapse"]	= "Wozu ist das Entfernen kleinerer Münzwerte gut?";
		["COMP_Help_WhatCollapseAnswer"]	= "Diese Einstellung entfernt die Münzen der kleinsten Wertigkeit aus der Anzeige, wenn deren Anzahl null ist. \nDies verkürzt die Länge der Preisanzeige, hat aber den Nebeneffekt, daß gleich aussehende Preise verschiedener Größenordnungen leicht verwechselt werden können (z.B. sieht 1s55c sehr ähnlich wie 1g55s aus). Um zu verhindern, daß Ihr mehr ausgebt, als Ihr eigentlich wollt, ist diese Einstellung abschaltbar.";
		["COMP_Help_WhatCompactUI"]	= "Was ist das CompactUI?";
		["COMP_Help_WhatCompactUIAnswer"]	= "CompactUI ist ein platz-optimiertes Suchfenster, das das Standard-Blizzard-Interface ersetzt. \nDa das normale Auktionshaus-Fenster dadurch stark verändert wird, kann es inkompatibel zu anderen Addons sein, die ebenfalls auf das Auktionhaus-Fenster zugreifen. In diesem Fall müßt Ihr Euch zwischen CompactUI und den anderen Addons entscheiden. Ihr könnt CompactUI einfach deaktivieren, in dem Ihr den Haken vor der 'CompactUI benutzen (benötigt Neustart)' Option im Einstellungsfenster entfernt.";
		["COMP_Help_WhatPopup"]	= "Was bewirkt das Einschalten der Popup-Hilfe?";
		["COMP_Help_WhatPopupAnswer"]	= "Zeigt einen kleinen Hilfs-Tooltip über verschiedenen Teilen des CompactUI-Fensters an.";
		["COMP_Help_WhatRequied"]	= "Was ist das erforderliche Gebot?";
		["COMP_Help_WhatRequiedAnswer"]	= "Die Standard-Oberfläche zeigt Euch euer momentanes Gebot. Im dem Fall daß das momentane Gebot nicht das Mindestgebot ist, wird der eigentliche Betrag eures Gebotes dieses momentane Gebot plus dem Mindestaufschlag sein. Daher werdet Ihr mehr zahlen müssen als im Fenster angezeigt wird, wenn Ihr nicht der erste Bieter seid. Durch Auswählen dieser Option könnt Ihr das Verhalten von CompactUI in dieser Hinsicht ändern, so daß statt dessen das erforderliche Gebot angezeigt wird, damit unabhängig davon, ob Ihr der erste Bieter seid oder nicht, stets der zu zahlende Betrag angezeigt wird.";
		["ILVL_Help_SlashHelp1"]	= "Hilfe für Auctioneer Advanced - iLevel";
		["ILVL_Help_SlashHelp2"]	= "Diese iLevel Hilfe.";
		["ILVL_Help_SlashHelp3"]	= "Lösche die aktuelle %s iLevel Preisdatenbank.";
		["ILVL_Help_SlashHelp5"]	= "Lösche iLevel Statistik für";
		["ILVL_Help_WhatConfidence"]	= "Was bedeutet Vertrauen?";
		["ILVL_Help_WhatConfidenceAnswer"]	= "Vertrauen ist ein Wert zwischen 0 und 1, das die Stärke der Kalkulationen bewertet (je höher, desto besser/aussage kräftiger).";
		["ILVL_Help_WhatFiltered"]	= "Was bedeutet Filtern?";
		["ILVL_Help_WhatFilteredAnswer"]	= "Gegenstände außerhalb einer (1.5*Standard) Varianz werden für die Kalkulation der Abweichung ignoriert und als (im Preis) falsch notiert bewertet.";
		["ILVL_Help_WhatIlevelStats"]	= "Was sind iLevel Statistiken?";
		["ILVL_Help_WhatIlevelStatsAnswer"]	= "iLevel Statistiken stehen für die Zahlen, die durch das iLevel Modul generiert werden, und stellen eine gefilterte Standardabweichungskalkulation der Gegenstandskosten dar.";
		["ILVL_Help_WhatNormalized"]	= "Was ist die normalisierte Kalkulation?";
		["ILVL_Help_WhatNormalizedAnswer"]	= "Kurz gefasst stellt dies den Durchschnitt all jener Werte dar, die innerhalb der Kalkulation der Standardabweichungsvarianz bestimmt werden.";
		["ILVL_Help_WhatStdDev"]	= "Was ist eine Standardabweichungskalkulation?";
		["ILVL_Help_WhatStdDevAnswer"]	= "Kurz gefasst stellt dies die Abweichung zur durchschnittlichen Durchschnittskalkulation dar.";
		["ILVL_Help_WhyStackSize"]	= "Warum gibt es die Option zur Multiplikation mit der Stapelgröße?";
		["ILVL_Help_WhyStackSizeAnswer"]	= "Das ursprüngliche Stat-iLevel multiplizierte mit der Stapelgröße des Gegenstands, aber manche bevorzugen es auf einer Pro-Gegenstand-Basis zu handeln.";
		["OUTL_Help_RemoveOldOutliers"]	= "Kann es alte Ausreißer entfernen?";
		["OUTL_Help_RemoveOldOutliersAnswer"]	= "Die einfache Antwort ist Nein, es arbeitet lediglich von diesem Punkt an. Sämtliche Einstellungen, die Sie vornehmen, werden von hier ab übernommen und sämtliche aktuellen Statistiken sind unberührt.\nDie komplexe Antwort? Nun ja, da gibt es diese Suppenschüssel...";
		["OUTL_Help_WhatOutlierFilter"]	= "Was ist der Ausreißer-Filter?";
		["OUTL_Help_WhatOutlierFilterAnswer"]	= "Beim Scannen von Auktionen kann der Preis der gewöhnlicheren Gegenstände Opfer von Leuten werden, die ein Vielfaches des eigentlichen Gegenstand-Wertes verlangen.\nDieser Filter entdeckt solche Ausreißer und verhindert, dass diese in den Datenstrom eingehen, wenn deren Wert einen spezifischen Prozentsatz des normalen Gegenstandswertes übersteigt. Gleichzeitig werden normale Preisfluktuationen von Gegenständen von Tag zu Tag zugelassen.";
		["PURC_Help_DayAverage"]	= "Also wird kein täglicher Durchschnitt gesichert?";
		["PURC_Help_DayAverageAnswer"]	= "Nein, das würde nicht nur Speicherplatz belegen, sondern auch viel Prozessorlast bei jedem Scan des Auktionshauses verursachen.";
		["PURC_Help_HowMovingAverage"]	= "Wie genau werden die gleitenden Tagesdurchschnitte kalkuliert?";
		["PURC_Help_HowMovingAverageAnswer"]	= "Der heutige gleitende Tagesdurchschnitt berechnet sich wie folgt: ((X-1)*GestrigerGleitenderTagesdurchschnitt + HeutigerDurchschnitt) / X, wobei X die Zahl der vermittelten Tage ist (3,7, or 14).";
		["PURC_Help_MultiplyStack"]	= "Wozu dient die Option zur Multiplikation der Stapelgrößen?";
		["PURC_Help_MultiplyStackAnswer"]	= "Das ursprüngliche Stat-Purchased Modul multiplizierte die Stapelgrößen mit dem Gegenstand, jedoch bevorzugen es manche auf Pro-Gegentands-Basis zu handeln.";
		["PURC_Help_SaferPrices"]	= "Wie werden die \"sicheren\" Preise berechnet?";
		["PURC_Help_SaferPricesAnswer"]	= "Für Alles, was mehr als 100 mal gesehen und mehr als 10 Mal pro Tag (im Durchschnitt) verkauft wird, verwenden wir einfach den 3-Tages-Durchschnitt.\nFür andere Auktionen bewerten wir den 7-Tages-Durchschnitt zu 50% sowie den 3- und 14-Tages-Durchschnitt zu zwischen 0-50% und 50-0% respektive, abhängig davon, wie häufig sie täglich gesehen werden (zwischen 1 und 7 Mal).";
		["PURC_Help_SlashHelp1"]	= "Hilfe für Auctioneer Advanced - Beschaffung";
		["PURC_Help_SlashHelp2"]	= "diese Beschaffungshilfe";
		["PURC_Help_SlashHelp3"]	= "Lösche die aktuelle {{%s}} Beschaffungspreis-Datenbank.";
		["PURC_Help_SlashHelp4"]	= "Erzwinge die Archivierung der täglichen {{%s}} Beschaffungsstatistik (lege einen neuen Tag an).";
		["PURC_Help_SlashHelp5"]	= "Archiviere die tägliche Statistik für {{%s}} und lege einen neuen Tag an.";
		["PURC_Help_WhatMovingAverage"]	= "Was ist mit \"gleitender Durchschnitt\" gemeint?";
		["PURC_Help_WhatMovingAverageAnswer"]	= "Gleitender Durchschnitt bedeutet, dass der gestrige gleitende Durschnitt höher gewichtet wird als der heutige. Der ermittelte Wert wird dann für die Berechnung am folgenden Tag verwendet.";
		["PURC_Help_WhatPurchasedStats"]	= "Was sind Beschaffungsstatistiken?";
		["PURC_Help_WhatPurchasedStatsAnswer"]	= "Beschaffungsstatistiken sind Zahlen, die vom Beschaffungs-Modul erzeugt werden. das Modul versucht zu ermitteln, ob eine Auktion mittels Sofortkauf oder einem Gebot gewonnen wurde. Es berechnet außerdem einen gleitenden Durchschnitt (3/7/14).";
		["SBTN_Help_WhatScanButton"]	= "Was sind die Scanbuttons?";
		["SBTN_Help_WhatScanButtonAnswer"]	= "Die Scannbuttons sind die Stop/Play/Pause/Schnellvorwärts Buttons im Auktionhausfenster.";
		["SDEV_Help_Confidence"]	= "Was ist mit Vertrauen gemeint?";
		["SDEV_Help_ConfidenceAnswer"]	= "Vertrauen gibt in einem Wert von 0 und 1 an, wie aussagekräftig die Kalkulation ist (ein höherer Wert ist besser)";
		["SDEV_Help_Filtered"]	= "Was meinst Du mit gefiltert?";
		["SDEV_Help_FilteredAnswer"]	= "Gegenstände außerhalb einer (1,5*Standard) Streuung werden ignoriert und als falsch ausgezeichnet betrachtet, wenn die Abweichung berechnet wird.";
		["SDEV_Help_Normalized"]	= "Was ist die normalisierte Kalkulation?";
		["SDEV_Help_NormalizedAnswer"]	= "Kurz gesagt: Das Mittel der Werte, die innerhalb der Standardabweichung der Streungsberechnung liegen.";
		["SDEV_Help_SlashHelp1"]	= "Hilfe für Auctioneer Advance - StdDev";
		["SDEV_Help_SlashHelp2"]	= "Das ist die StdDev Hilfe";
		["SDEV_Help_SlashHelp3"]	= "Lösche die aktuelle %s StdDev Preisdatenbank.";
		["SDEV_Help_SlashHelp4"]	= "Lösche StdDev Statistiken für";
		["SDEV_Help_StandardDeviationCalculation"]	= "Was ist eine Standardabweichungskalkulation?";
		["SDEV_Help_StandardDeviationCalculationAnswer"]	= "Kurz gefasst handelt es sich hierbei um den Abstand zur durchschnittlichen Durchschnittskalkulation.";
		["SDEV_Help_StdDevStats"]	= "Was sind StdDev Statistiken?";
		["SDEV_Help_StdDevStatsAnswer"]	= "StdDev Statistiken sind Zahlen, die von dem StdDev Modul generiert werden und aus einer gefilterten Standardabweichungskalkultion der Gegenstandskosten besetehen.";
		["SDEV_Help_WhyMultiplyStack"]	= "Warum gibt es die Option der Multiplikation mit der Stapelgröße?";
		["SDEV_Help_WhyMultiplyStackAnswer"]	= "Das ursprüngliche Stat-StdDev Modul multiplizierte mit der Stapelgröße des Gegenstandes, jedoch handeln manche lieber auf einer Pro-Gegenstands-Basis.";
		["SHTG_Help_SlashHelp1"]	= "Hilfe für Auctioneer Advanced - Histogramm";
		["SHTG_Help_SlashHelp2"]	= "Diese Histogramm Hilfe.";
		["SHTG_Help_SlashHelp3"]	= "Lösche die aktuelle %s Histogramm Preisdatenbank.";
		["SHTG_Help_SlashHelp5"]	= "Lösche Histogramm Statistiken für";
		["SHTG_Help_WhatAdvantageHistogram"]	= "Welche Vorteile hat Histogramm?";
		["SHTG_Help_WhatAdvantageHistogramAnswer"]	= "Histogramm Statistiken werden nicht in Anzahl und Dauer limitiert. Sie können Daten speichern, so dass auch absatzstarke Produkte beobachtet werden können.";
		["SHTG_Help_WhatDisadvantagesHistogram"]	= "Welche Nachteile hat Histogramm?";
		["SHTG_Help_WhatDisadvantagesHistogramAnswer"]	= "Histogramm rundet die Preise geringfügig, um sie leichter abspeichern zu können. Dies führt also zu einem geringfügigen Präzisionsverlust. Jedoch ist es auf 1/250 des Marktpreises genau (d.h. die Preise eines Gegenstands zu einem Marktpreis von 250g werden auf 1g genau abgespeichert).";
		["SHTG_Help_WhatHistogramStats"]	= "Was sind Histogramm Statistiken?";
		["SHTG_Help_WhatHistogramStatsAnswer"]	= "Histogramm Statistiken zeichnen ein Zeitdiagramm vergangener Preise auf.";
		["SHTG_Help_WhatIQR"]	= "Was ist das IQR?";
		["SHTG_Help_WhatIQRAnswer"]	= "Das IQR ist ein Verteilungsmaß. Der Mittelteil der zu sehenden Preise wird innerhalb das IQR Bereichs eingeschränkt. Ein Gegenstand zu durchschnittlich 100g und IQR 10g verfügt über sehr konsistente Daten. Beträgt der IQR 100g, schwankten die Preise erheblich.";
		["SHTG_Help_WhatMedian"]	= "Was ist der Median (Zentralwert)?";
		["SHTG_Help_WhatMedianAnswer"]	= "Der Median bzw. Zentralwert ist der Wert, wo die eine Hälfte der Preise überhalb und die andere Hälfte unterhalb liegt.";
		["SIMP_Help_AverageMinimumBuyout"]	= "Was ist der Sinn des mittleren minimalen Sofortkaufpreises?";
		["SIMP_Help_AverageMinimumBuyoutAnswer"]	= "Damit könnt Ihr den richtigen Zeitpunkt zum Kaufen und Verkaufen ermitteln. Wenn der MBO (minimum buyout - minimaler Sofortkaufpreis) größer ist als der Durchschnittswert, dann ist ein guter Zeitpunkt zum Verkaufen, und wenn der Durchschnittpreis höher als der MBO ist, ist ein guter Zeitpunkt zum Kaufen.";
		["SIMP_Help_HowAveragesCalculated"]	= "Wie wird der fortlaufende Tages-Durschnittswert kalkuliert?";
		["SIMP_Help_HowAveragesCalculatedAnswer"]	= "Heutiger fortlaufender Durschnittswert ist: ((x-1)*gestriger fortlaufender Durschnittwert + heutiger Durschnittswert) / X, wobei X die Anzahl der Tage ist (3, 7 oder 14)";
		["SIMP_Help_MinimumBuyout"]	= "Warum sollte ich den minimalen Sofortkaufpreis wissen?";
		["SIMP_Help_MinimumBuyoutAnswer"]	= "Während manche Gegenstande sich im Durchschnitt innerhalb von 2 Tagen sehr gut verkaufen, könnten sich andere nur zu den niedrigsten angegebenen Preisen verkaufen lassen. Da es sich hierbei um eine sehr einfache Kalkulation handelt, wurde es diesem Modul hinzugefügt.";
		["SIMP_Help_MinimumBuyoutVariance"]	= "Wofür gibt es die \"10% Varianz\", die vorher erwähnt wurde?";
		["SIMP_Help_MinimumBuyoutVarianceAnswer"]	= "Ist der aktuelle MBO innerhalb einer 10% Reichweite des laufenden Durchschnitts, wird der aktuelle MBO auf einen laufenden Durchschnitt von 50% (normal) gemittelt. Ist der aktuelle MBO außerhalb einer 10% Reichweite, wird der aktuelle MBO nur mit einer 12,5% Rate gemittelt.";
		["SIMP_Help_MovingAverage"]	= "Was bedeutet \"gleitender Tagesdurchschnitt\"?";
		["SIMP_Help_MovingAverageAnswer"]	= "Gleitender Durchschnitt bedeutet, daß der gestrige gleitende Durschnitt höher gewichtet wird als der heutige. Der ermittelte Wert wird dann für die Berechnung am folgenden Tag benutzt.";
		["SIMP_Help_NoDaySaved"]	= "Also speichert Auctioneer keine täglichen Durchschnittswerte?";
		["SIMP_Help_NoDaySavedAnswer"]	= "Nein, das würde nicht nur viel Speicherplatz benötigen, sondern auch aufwendige Berechnungen bei jeder Auktionshausabfrage erfordern, dies ist aber nur ein einfaches Modell.";
		["SIMP_Help_SimpleStats"]	= "Was sind 'Simple Stats'?";
		["SIMP_Help_SimpleStatsAnswer"]	= "'Simple Stats'\" sind die Zahlen die vom 'Simple'-Modul generiert werden; das 'Simple'-Modul berechnet alle Durchschnittspreise aller Gegenstände die es kennt und stellt den gleitenden 3-, 7- und 14-tägigen Durchschnitt zur Verfügung. Ausserdem stellt es einen täglichen Mindestverkaufswert zur Verfügung, zusammen mit einem fortlaufenden Durchschnitts-Mindestverkaufswert, innerhalb einer 10%-Abweichung.";
		["SIMP_Help_SlashHelp1"]	= "Hilfe für Auctioneer Advanced - 'Simple'";
		["SIMP_Help_SlashHelp2"]	= "Dies ist die Hilfe für das Modul 'Simple'.";
		["SIMP_Help_SlashHelp3"]	= "lösche aktuelle 'Simple' Preis-Datenbank";
		["SIMP_Help_SlashHelp4"]	= "Erzwinge eine Archivierung der %s täglichen 'Simple'-Statistiken (beginne neuen Tag)";
		["SIMP_Help_SlashHelp6"]	= "Archiviere {{%s}} tägliche Statistiken und beginne einen neuen Tag";
		["SIMP_Help_SlashHelpClearingData"]	= "%s - Simple: Lösche die Daten für %s für {{%s}}";
		["SIMP_Help_WhyMultiplyStack"]	= "Warum habe ich die Option die Stapelgröße zu multiplizieren?";
		["SIMP_Help_WhyMultiplyStackAnswer"]	= "Der originale 'Stat-Simple'-Wert wird mit der Grösse des Stapels multipliziert, aber manche möchten es in pro-Item angezeigt haben.";
		["SIMP_Help_WhyVariance"]	= "Welchen Sinn hat eine Abweichung beim Mindestverkaufswert?";
		["SIMP_Help_WhyVarianceAnswer"]	= "Weil einige Spieler ihr Gegenstände zu unverschämten oder zu Spottpreisen verkaufen wollen, so sieht man den vernüftigen Durchschnittsverkaufspreis";
		["SPRG_Help_WhatScanProgress"]	= "Was ist die Fortschrittsanzeige?";
		["SPRG_Help_WhatScanProgressAnswer"]	= "Die Fortschrittsanzeige erscheint während des Aktionshaus-Scans. Sie zeigt die Geschwindigkeit des Scans, die momentane und die gesamte Anzahl der Auktionen, sowie die Anzahl der bisher gescannten Seiten und die Gesamtzahl der Seiten an.";
		["UCUT_Help_WhatUndercut"]	= "Was ist das 'Unterbieten'-Modul?";
		["UCUT_Help_WhatUndercutAnswer"]	= "Das 'Unterbieten'-Modul erlaubt es alle derzeit verfügbaren Auktionen (Konkurrenten) zu unterbieten, anhand Deiner Einstellungen.\nEs wird empfohlen, 'Unterbieten' nach allen anderen Vergleichsmodulen laufen zu lassen.";

		-- Section: HelpTooltip
		["AAMU_HelpTooltip_AutoSellBOP"]	= "Unbenutzbare seelengebundene Gegenstände automatisch verkaufen";
		["AAMU_HelpTooltip_AutoSellBOPNoPrompt"]	= "Es wird keine Bestätigung für den Verkauf von seelengebundenen Gegenständen erscheinen, die diese Charakterklasse nicht benutzen kann.";
		["AAMU_HelpTooltip_AutoSellGrey"]	= "Graue Gegenstände automatisch beim Händler verkaufen.";
		["AAMU_HelpTooltip_AutoSellList"]	= "Markiere die Box, um die Auto-Sell-Einstellungen anzupassen.";
		["AAMU_HelpTooltip_AutoSellListItems"]	= "Gegenstände auf der ständigen Händlerliste automatisch verkaufen.";
		["AAMU_HelpTooltip_AutoSellListNoPrompt"]	= "Es wird kein Bestätigungsfenster eingeblendet, wenn Gegenstände auf der ständigen Händlerliste verkauft werden.";
		["AAMU_HelpTooltip_AutoSellReason"]	= "Mit Hilfe der Händlersuche gekaufte Gegenstände automatisch verkaufen";
		["AAMU_HelpTooltip_AutoSellReasonNoPrompt"]	= "Für Gegenstände mit \"zum Verkauf gekauft\"-Tag wird kein Bestätigungsfenster eingeblendet.";
		["AAMU_HelpTooltip_AutoStop12"]	= "Erlaubt den Rückkauf versehentlich verkaufter Gegenstände - der Server speichert die letzten 12 Verkäufe an Händler.";
		["AAMU_HelpTooltip_BeginnerTooltip"]	= "Anfänger-Tooltips anzeigen.";
		["AAMU_HelpTooltip_Chatspam"]	= "Chatnachrichten von AutoMagic anzeigen.";
		["AAMU_HelpTooltip_MailButtons"]	= "Öffnet die Oberfläche der Einstellungen für die benutzerdefinierten Tasten, erzeugt eine individuelle Liste von Gegenständen, die versenden wird";
		["AAMU_HelpTooltip_MailGUI"]	= "Zeige das Auto-Mail Fenster am Briefkasten.";
		["AAMU_HelpTooltip_OverrideSUIMail"]	= "Benutze die ItemSuggest-Regeln statt der SearchUI 'Gekauft für'-Regeln beim Sortieren der Post.";
		["AAMU_HelpTooltip_Vendoring"]	= "Aktiviert die Auto-Sell Option.";
		["ADV_HelpTooltip_AltChatLinkLeft"]	= "Aktiviert die Funktion einen Tooltip im Chat mit ALT+Linksklick zu öffnen.";
		["ADV_HelpTooltip_ChatOutputFrame"]	= "Chatfenster, in dem Auctioneer seine Ausgaben anzeigen soll.";
		["ADV_HelpTooltip_CopyProfile"]	= "Erstelle oder überschreibe ein Profil mit dem angegebenen Profilnamen. Alle Einstellungen werden vom aktuellen Profil kopiert.";
		["ADV_HelpTooltip_HybridScanning"]	= "Für sehr große Auktionshäuser kann der GetAll-Scan nicht alle Auktionen abfragen. Ein Hybrid-Scan wird normal-scanning aktivieren um die Auktionen die bei der Get-All-Scann fehlen, abzufragen";
		["ADV_HelpTooltip_MarketValueAccuracy"]	= "Genauigkeit der Marktpreisberechnung. Gibt die maximale Fehlertoleranz an. Höhere Werte erhöhen die Systemleistung auf Kosten geringerer Genauigkeit.";
		["ADV_HelpTooltip_MktPrice"]	= "Aktiviert die Anzeige des Marktpreises im Tooltip. Bei gedrückter SHIFT-Taste werden alle Komponenten der Preisermittlung angezeigt.";
		["ADV_HelpTooltip_ModTTShow"]	= "Immer: Auctioneer-Tooltips werden immer angezeigt\nbei gedrückter ALT-Taste: Auctioneer-Tooltips werden angezeigt, wenn ALT gedrückt wird\nbei NICHT gedrückter ALT-Taste: Auctioneer-Tooltips werden angezeigt, wenn ALT NICHT gedrückt wird\nNie: Auctioneer-Tooltips werden nie angezeigt.";
		["ADV_HelpTooltip_MultiplyStack"]	= "Vervielfacht um die momentane Stapelgröße, wenn aktiviert";
		["ADV_HelpTooltip_NewProfile"]	= "Erstelle oder überschereibe ein Profil mit dem angegebenen Profilnamen. Alle Einstellungen werden zurückgesetzt.";
		["ADV_HelpTooltip_NoScanDataWarning"]	= "Wähle diese Option, wenn Du häufig das Auc-ScanData AddOn deaktivierst um Speicher zu sparen. Warnung: Die meisten Statistiken können nicht aufgezeichnet werden, wenn ScanData nicht geladen ist.";
		["ADV_HelpTooltip_PostClearOnClose"]	= "Wenn das Auktionshaus geschlossen wird, wird das Abarbeiten der Warteschlange beendet";
		["ADV_HelpTooltip_PostConfirmOnClose"]	= "Wenn das Auktionshaus geschlossen wird, fragt ein Popup-Dialog, ob das Abarbeiten der Warteschlange beendet werden soll.";
		["ADV_HelpTooltip_PreferredLanguage"]	= "Wählt die Sprache, die von Auctioneer benutzt wird. Eine Änderung wird erst nach Neustart oder /reloadui aktiv.";
		["ADV_HelpTooltip_ProcessingTargetFPS"]	= "Stellt die Frame Rate während des Scans ein. Höhere Werte führen zu einer gleichmäßigeren Anzeige, aber der Scan benötigt mehr Zeit.";
		["ADV_HelpTooltip_ProgressBar"]	= "Fortschrittsbalken anzeigen, während Auctioneer Daten erfasst.";
		["ADV_HelpTooltip_ResetProfile"]	= "Setze alle Einstellungen im aktuellen Profil zurück.";
		["ADV_HelpTooltip_ScanAllQueries"]	= "Aktivieren um alle Suchen im Auktionshaus zu scannen. Deaktivieren um nur Auctioneers Suchen zu nutzen.\nBei Problemen mit anderen Add-Ons deaktivieren.";
		["ADV_HelpTooltip_ScanDataDisplay"]	= "Aktiviert die Anzeige der Anzahl an Gegenständen im aktuell gescannten Abbild, die diesem Gegenstand entsprechen.";
		["ADV_HelpTooltip_ScanDataForce"]	= "Die Scandaten werden zusammen mit dem ersten Laden von Auctioneer geladen und nicht erst dann, wenn sie zum ersten Mal benötigt werden.";
		["ADV_HelpTooltip_ScanDataModifier"]	= "Aus den Scandaten werden nur genaue Übereinstimmungen angezeigt, außer die Umschalttaste wird gedrückt gehalten.";
		["ADV_HelpTooltip_ScanDataSummary"]	= "Zusammenfassung der Datenermittlung anzeigen.";
		["ADV_HelpTooltip_ScanDataSummaryFull"]	= "Zeigt die Anzahl der Änderungen nach einem Update der Auktionsdatenbank an.";
		["ADV_HelpTooltip_ScanDataSummaryMicro"]	= "Zeigt die Anzahl der Änderungen nach einem Update für einen einzelnen Gegenstand an.";
		["ADV_HelpTooltip_ScanDataSummaryPartial"]	= "Zeigt eine Übersicht der Veränderungen nach einem Update von nur einer Kategorie an.";
		["ADV_HelpTooltip_ScanRetrieveTTL"]	= "Die Anzahl der Sekunden, die Auctioneer ohne neue Daten zu erhalten wartet, bevor der Scan gestoppt wird.\nErhöhen falls Deine Scanergebnisse keine Unterschiede liefern.";
		["ADV_HelpTooltip_ScanSellerNames"]	= "Weitere Scans durchführen um mehr Daten über Verkäufernamen zu bekommen. Wenn nicht aktiviert, werden Scans schneller, aber einige Filter und Suchen werden nicht funktionieren.";
		["ADV_HelpTooltip_SearchClickHooks"]	= "Schaltet Click-Hooks für die Suche ein.";
		["ADV_HelpTooltip_ShowPurchaseDebug"]	= "Zeigt hinzugefügte Gegenstände in die Kauf Warteschlange und welche bereits gekauft wurden.";
		["ADV_HelpTooltip_ShowTooltipInCombat"]	= "Aktiviert die Anzeige der erweiterten Auctioneer Werkzeughilfe während des Kampfes. Die Auctioneer Werkzeughilfe können sporadisch auftretende kurze Standbilder verursachen, am Besten bleiben sie deshalb während des Kampfes ausgeschaltet.";
		["ADV_HelpTooltip_UnresolvedAuctionsTolerance"]	= "Maximale Anzahl der unlösbaren Auktionen für einen vollständigen Scan darf noch als Komplett behandelt werden";
		["ADV_Help_ActivateProfile"]	= "Wähle das Profil, das du für diesen Charakter verwenden möchtest.";
		["ADV_Help_DeleteProfile"]	= "Das derzeit ausgewählte Profil löschen.";
		["ADV_Help_ProfileName"]	= "Gib den Namen des Profils ein, das du erstellen möchtest.";
		["AHWC_HelpTooltip_AllowMovable"]	= "Diese Option aktivieren, um das Auktionsfenster verschieben zu können.";
		["AHWC_HelpToolTip_AuctionHouseScale"]	= "Diese Option erlaubt es, die Skalierung des Auktionsfensters zu verändern. Standard ist 1.";
		["AHWC_HelpTooltip_CompactUIFontScale"]	= "Ermöglicht die Anpassung der Text-Größe des \"CompactUI\" in der Registerkarte \"Browse\". Standard ist 0.";
		["AHWC_HelpToolTip_PreventClosingAuctionHouse"]	= "Diese Option verhindert das Schliessen des Auktionsfensters wenn andere Fenster geöffnet werden, entsprechend deiner Einstellungen.";
		["AHWC_HelpToolTip_ProtectProcessing"]	= "Diese Option aktivieren, um das Fenster zu sperren, bis alle Prozesse abgeschlossen sind.";
		["AHWC_HelpToolTip_RemberLastPosition"]	= "Diese Option aktivieren, um das Auktionsfenster an der letzten Position zu öffnen";
		["AHWC_HelpTooltip_SearchUIScale"]	= "Diese Option erlaubt es die Skalierung der SearchUI zu verändern. Standard ist 1.";
		["APPR_HelpTooltip_AlsoShowBid"]	= "Diese Option lässt Appraiser die Startpreise auch im Tooltip anzeigen.";
		["APPR_HelpTooltip_AltClickingAppraiserSetting"]	= "Diese Option erlaubt die Verwendung von Alt+Klick auf Gegenstände um die Appraiser-Einstellungen für die Anpassung aufzurufen. \nIst nur aktiv während das Appraiser-Fenster geöffnet ist.";
		["APPR_HelpTooltip_AlternatePricingModelSelectBox"]	= "Sie können für Gegenstände, die kein spezifisches Preismodell haben, ein Standard- und ein alternatives Preismodell wählen.";
		["APPR_HelpTooltip_BidSelectedAuction"]	= "Bietet auf die ausgewählte konkurrierende Auktion";
		["APPR_HelpTooltip_BuyoutSelectedAuction"]	= "Sofortkauf der ausgewählten konkurrierenden Auktion";
		["APPR_HelpTooltip_ClearsPostQueue"]	= "Löscht die Post-Warteschlange";
		["APPR_HelpTooltip_ColorAppraiserPriceLevel"]	= "Diese Option benutzt die Information von PreisLevel, um die Abweichung der gegenwärtigen Preise vom Mittelwert in Schattierungen von rot nach blau anzuzeigen.";
		["APPR_HelpTooltip_ColorManifestByPriceLevel"]	= "Diese Option benutzt Informationen des Preislevels um die im rechten Popup-Rahmen zu findenden Pro-Stück- und Aufkauf-Preise passend einzufärben.";
		["APPR_HelpTooltip_DefaultListingDuration"]	= "Sie können eine Standarddauer für Gegenstände setzen, die keine spezifische Dauer eingestellt haben.";
		["APPR_HelpTooltip_DefaultModelAppraisals"]	= "Sie können ein Standard- oder alternatives Preismodell für Gegenstände wählen, für die noch kein spezielles Modell festgelegt wurde.";
		["APPR_HelpTooltip_DefaultNumberStacks"]	= "Füge eine Nummer oder 'maxfull' oder 'maxplus' ein um die Standardanzahl an Stapeln festzulegen. 'maxfull'= alle vollen Stapel, 'maxplus' = alle (auch unvollstaendige) Stapel";
		["APPR_HelpTooltip_DefaultStackSize"]	= "Tragen Sie die Anzahl oder 'max' für die Standard-Stapelgröße ein.";
		["APPR_HelpTooltip_EnablesMatchersCalculatingPrices"]	= "Aktiviert Vergleichsmodule (z.B. Unterbieten) bei der Preiskalkulation.";
		["APPR_HelpTooltip_EnterBidAmount"]	= "Geben Sie einen neuen Gebotsbetrag ein, um einen festen Preis zu setzen.";
		["APPR_HelpTooltip_EnterBuyoutFixedPrice"]	= "Geben Sie einen neuen Sofortkaufbetrag ein, um einen festen Preis zu setzen.";
		["APPR_HelpTooltip_FlagsBatchPosting"]	= "Markiert den Gegenstand für die Stapelverarbeitung.";
		["APPR_HelpTooltip_HowIgnoreSeller"]	= "ALT-Klickt auf den Verkäufer, den Ihr ignorieren möchtet und wählt Ja im Popup-Fenster. Der Name des Verkäufers wird rot markiert und in die Ignorierliste des BASIC-FILTER Moduls übernommen.";
		["APPR_HelpTooltip_HowUnIgnoreSeller"]	= "ALT-Klickt auf den Verkäufer, den Ihr aus der Ignorierliste entfernen möchtet und bestätigt das Popup-Fenster mit Ja. Der Name des Verkäufers wird aus der Ignorierliste des BASIC-FILTER Moduls entfernt.";
		["APPR_HelpTooltip_IncludeAuctionsListing"]	= "Eigene Auktionen in der Gegenstandsliste anzeigen.";
